W=[
E('easy','/ˈiːzi/','容易的；轻松的；自在的','做起来不用拧紧全身的劲，或者待在那里心里没有紧绷感。','现代可认作 ease + -y；历史也接法语 aisié“被安顿得舒服的”。古法语 aise 的更早来源不确定，和拉丁 adiacens 的联系是一种分析。',EY,'an easy task 不费力；an easy manner 让人感到自然不拘束。take it easy 是放松、别太紧张，不必逐字理解为拿东西。','easy to understand；an easy smile；take it easy。','simple 说结构不复杂；easy 说做起来不难。一个规则很简单的任务，也可能很难完成。',('The instructions are easy to follow.','说明很容易照着做。'),('Her easy manner helped everyone relax.','她自然随和的举止让大家放松了下来。'),sources=['https://www.etymonline.com/word/easy','https://en.wiktionary.org/wiki/easy']),
E('easily','/ˈiːzɪli/','轻易地；容易地；毫无疑问地','动作完成时没遇到多少阻力；有时也表示比较结果很明显，根本不费劲就能看出。','easy + -ly，y 改 i；英语中的副词构词，不需要另找一个拉丁副词。',EY+[['中古英语 esy + -ly → easily','容易的 → 不费力地']], '常修饰能不能做到：can easily reach；也可加强最高级，easily the best 表示明显是最好的。否定时 not easily 是不容易，并不等于绝不可能。','can easily；easily damaged；easily the best。','easy 是形容词；easily 通常修饰动作。This is easy，但 She did it easily。',('The lid comes off easily if you turn it slowly.','慢慢转动的话，盖子很容易取下。'),('This was easily the clearest explanation in the book.','这显然是书里最清楚的一段解释。')),
E('ease','/iːz/','自在；轻松；缓解；使逐渐移动','把绷着的状态松开：紧张少了、难度低了，动作也可以放慢变柔和。','名词经法语 aise、ese 借入；动词另经古法语 aiser“使舒服”。更早连到拉丁 adiacens 的说法有争议，不能讲成已经证实的直系链。',EA+[['同源动词支线：古法语 aiser → 中古英语 esen → ease','缓解；让动作平缓进行']], 'with ease 是轻松地；at ease 是自在。ease the pressure 是减轻压力；ease a box through a doorway 是小心慢慢让箱子通过。','at ease；with ease；ease pressure；ease into…。','relax 常说人或肌肉放松；ease 可以说困难、拥堵、负担减少，也能说缓缓移动。',('A short walk helped ease the tension in the room.','出去走一小会儿，缓和了屋里的紧张气氛。'),('She eased the heavy box through the narrow doorway.','她小心地把沉重的箱子慢慢挪过狭窄门口。'),sources=['https://www.etymonline.com/word/ease','https://en.wiktionary.org/wiki/ease']),
E('adjacent','/əˈdʒeɪsənt/','相邻的；邻近的','两样东西并排待着，目光从一个移到另一个，中间不用跨过同类的第三个。','拉丁 ad- 朝向、在旁 + iacēre 躺着、位于，形成 adiacens“位于旁边的”；英语有拉丁及盎格鲁法语借入背景。',AD,'adjacent to 是位于旁边。日常不必每次都真的接触；数学里相邻顶点、相邻角有各自严格规则，不能只看图上距离近。','adjacent to；adjacent rooms；adjacent pages。','nearby 只说不远；adjacent 通常更明确指旁边、前后紧邻的位置。',('The workshop is in the room adjacent to the library.','工作坊在图书馆旁边的房间里。'),('The two labels appear on adjacent pages.','两个标签出现在前后相邻的页面上。'),sources=['https://www.merriam-webster.com/dictionary/adjacent','https://www.etymonline.com/word/adjacent']),
E('uneasy','/ʌnˈiːzi/','不安的；不自在的；不稳固的','事情还没真的出问题，心里已经觉得哪里不太对，没法安心放松。','否定 un- + easy，在英语中形成；并不是把拉丁词根中的某段字母拿掉。',EY+[['中古英语 un- + easy → uneasy','不自在；不安心']], 'uneasy about something 是对某事担心。an uneasy peace 则表示表面和平却并不踏实，矛盾仍在。不要用 uneasy 泛指所有做起来难的事。','feel uneasy；uneasy about；an uneasy silence。','difficult 是任务难；uneasy 重点是心理不安或关系不稳，不是 easy 的所有义项都直接反过来。',('I felt uneasy about leaving the door unlocked.','不锁门就离开，让我有些不安。'),('An uneasy silence followed the announcement.','宣布之后是一阵令人不自在的沉默。')),
E('unease','/ʌnˈiːz/','不安；忧虑；不自在','没有明确的惊恐发作，只是心里始终有一小块悬着，放不下来。','un- 不 + ease 自在，接中古英语 unese。早期也说身体不适，现代常指心理上的不安。',EA+[['中古英语 un- + ese → unese → unease','不舒服 → 心理不安']], '通常是不可数名词。a sense of unease 是一阵或一种不安感；growing unease 表示担忧渐渐加重。','a sense of unease；growing unease；unease about…。','uneasy 是人的状态或气氛的性质；unease 是这种不安本身。',('There was growing unease about the unexplained delay.','对这次没有解释的延误，大家越来越不安。'),('The empty corridor gave her a sense of unease.','空荡荡的走廊让她感到有些不安。'),sources=['https://www.etymonline.com/word/unease']),
E('easygoing','英 /ˌiːziˈɡəʊɪŋ/；美 /ˌiːziˈɡoʊɪŋ/','随和的；不爱计较的','相处时不用怕处处踩中他的雷区，小变化、小麻烦一般能轻松接受。','easy + going，英语复合形容词；going 在这里参与描述一个人的处事方式，不是强调走路速度。',EY+[['英语 easy + going → easygoing','处事轻松、不苛求的']], '多形容人、性格或氛围。一般是正面描述，但随和不等于没有原则，也不保证工作粗心。词典也常收连字符写法。','an easygoing person；an easygoing atmosphere。','careless 是不仔细，easygoing 是不紧绷、不爱计较，两者不能混。',('Our easygoing host told us to arrive whenever we were ready.','随和的主人让我们准备好了再过去，不必赶时间。'),('She has an easygoing manner but takes deadlines seriously.','她态度随和，但对截止时间很认真。')),
E('adjacency','/əˈdʒeɪsənsi/','相邻；邻接关系','不再描述某一件东西“在旁边”，而是把两个东西彼此挨着这件事当成一个关系。','与 adjacent 对应，现代可按 -ent → -ency 理解；词源有后期拉丁 adjacentia 借入说，也有英语 adjacence + -y 分析。',J+[['拉丁 adiacēre → adiacens；相关名词 adjacentia','位于旁边 → 邻近区域、邻接'],['英语 adjacence / adjacency','相邻的状态或关系']], '地图和布局中说位置邻近；图论里两顶点有边相连才相邻，不能把纸上画得近误当成邻接。adjacency matrix 用表格记录这种连接。','adjacency to；an adjacency matrix；an adjacency list。','proximity 是接近程度；adjacency 通常是在问是否构成某种邻接关系。',('The architect used adjacency to make the kitchen and dining room work together.','建筑师利用相邻布局，让厨房和餐厅衔接起来。'),('The adjacency matrix records which vertices are connected by an edge.','邻接矩阵记录哪些顶点之间有边相连。'),sources=['https://www.dictionary.com/browse/adjacency','https://en.wiktionary.org/wiki/adjacency','https://arxiv.org/abs/1809.00162']),
E('joist','/dʒɔɪst/','托梁；楼板搁栅','地板下面一根根横着撑住木板的梁，像给上面的板铺了一排能躺稳的支架。','拉丁 iacēre 经古法语 gesir“躺着”，其分词名词 giste 指支撑梁；中古英语 gist / giste 后变成 joist。不是 join“连接”的缩写。',JO,'通常是一组平行的水平构件，支撑楼板或天花板，可用木、钢等材料。词本身不指定所有建筑结构的具体设计。','floor joists；ceiling joists；a timber joist。','beam 是梁的较宽泛名称；joist 常指成排铺设、承托楼面等的较小水平梁。',('The carpenter checked each floor joist before laying the boards.','木匠铺地板前检查了每根托梁。'),('Insulation was fitted between the ceiling joists.','保温材料装在天花板搁栅之间。'),sources=['https://www.etymonline.com/word/joist']),
E('subjacent','/sʌbˈdʒeɪsənt/','位于下面的；下伏的〔较正式〕','把一块表层掀开，底下紧接着的那一层就在 subjacent 的位置。','拉丁 sub- 在下 + iacēre 位于 → subiacēre，借其现在分词 subiacens〔subjacent-〕形成英语词。',J+[['拉丁 sub- + iacēre → subiacēre；分词 subiacens','位于下方；下伏的'],['英语 subjacent','位于下面的']], '常用于地层、组织层次等说明。它讲空间或结构上的下方，不自动表示地位低、不重要。','subjacent rock；subjacent tissue。','adjacent 是在旁边；subjacent 是在下面。普通叙述也可用 underlying。',('Water collected above the subjacent layer of clay.','水积在下伏黏土层的上方。'),('The drawing shows the surface and the subjacent tissue.','图中显示了表面及其下方的组织。'),sources=['https://en.wiktionary.org/wiki/subjacent']),
E('circumjacency','英 /ˌsɜːkəmˈdʒeɪsənsi/','环绕的状态；周围环境〔罕见〕','把中心和四周分开看，四周围着的地带或围绕关系就是这个词要说的。','对应 circumjacent“位于四周的”，以 -ency 表示状态；其词基接拉丁 circumiacens，不能拆成英语 circle 加 adjacent。',CI+[['英语 circumjacent → circumjacency','环绕的 → 周围地带或环绕状态']], '可见于旧式地理、哲学或文学表述。今天描述普通周边环境，多用 surroundings；保留它用于读懂旧文。','the circumjacency of a site〔少见〕。','circumjacent 是形容词，circumjacency 是名词；不是一个具体圆周的长度。',('The old survey describes the castle and its circumjacency.','旧调查描述了城堡及周围环境。'),('The essay treats the circumjacency of the hills as part of the scene’s character.','文章把群山环绕的格局看作这一景色的特点之一。'),sources=['https://www.collinsdictionary.com/dictionary/english/circumjacency','https://en.wiktionary.org/wiki/circumjacency']),
E('circumjacent','英 /ˌsɜːkəmˈdʒeɪsənt/；美 /ˌsɜːrkəmˈdʒeɪsənt/','周围的；环绕着的〔书面、少见〕','站在某个中心，四面望去，周围分布着的地区或事物就是 circumjacent。','借拉丁 circumiacens，现在分词来自 circum- 四周 + iacēre 位于；保留了位置状态的意思。',CI,'常修饰 lands、hills、villages，强调相对于某个中心处在四周。并不要求它们排成完美的圆。','circumjacent lands；circumjacent hills。','surrounding 通用自然；circumjacent 带旧式或学术书面色彩。',('The map marks the town and the circumjacent villages.','地图标出了小镇和周围村庄。'),('The ruined tower overlooks the circumjacent fields.','残破的塔楼俯瞰周围田野。'),sources=['https://www.merriam-webster.com/dictionary/circumjacent']),
E('interjacent','英 /ˌɪntəˈdʒeɪsənt/；美 /ˌɪntərˈdʒeɪsənt/','介于中间的；位于其间的〔少见〕','先看两端，再把注意力移到夹在它们中间的那块地方或那一段内容。','拉丁 inter- 在……之间 + iacēre 位于 → interiacēre；借分词 interiacens 形成英语 interjacent。',J+[['拉丁 interiacēre → interiacens','处在两者之间'],['英语 interjacent','介于其间的']], '可说两处之间的地区，也可书面地说夹在文字之间的说明。现代普通表达常用 intervening 或 between。','interjacent land；interjacent remarks。','interjacent 只说明处在其间；intermediate 有时还强调等级、阶段居中。',('A narrow strip of interjacent land separates the two farms.','一条狭窄的中间地带隔开了两座农场。'),('The editor removed the interjacent remarks to make the argument clearer.','编辑删去了夹在其中的评语，让论证更清楚。'),sources=['https://www.merriam-webster.com/dictionary/interjacent','https://en.wiktionary.org/wiki/interjacent']),
E('interjoist','美 /ˈɪntərˌdʒɔɪst/','两根托梁之间的空隙；中间托梁〔旧木工用语〕','看地板下面的排排横梁，两根梁之间留出来的那一道空当，就是最常记录的 interjoist。','英语 inter- 之间 + joist 托梁；joist 本身经法语接拉丁 iacēre，整个词不是古罗马已有的建筑名词。',JO+[['英语 inter- + joist → interjoist','托梁之间的空隙；中间的横梁']], '这是少见木工词，主流词典记录梁间空隙；旧词书也记中间梁义。读图纸或旧文时，要看它是在指空位还是构件。','an interjoist space；the width of an interjoist〔少见〕。','joist 是实体梁；interjoist 常说梁与梁之间的空位，不要把保温材料填在梁本身里面。',('The old plan gives the width of each interjoist.','旧图纸标出了每道梁间空隙的宽度。'),('The carpenter placed insulation in the interjoists.','木匠在托梁之间的空隙里放入保温材料。'),sources=['https://www.collinsdictionary.com/us/dictionary/english/interjoist','https://en.wiktionary.org/wiki/interjoist']),
E('nonadjacent','英 /ˌnɒnəˈdʒeɪsənt/；美 /ˌnɑːnəˈdʒeɪsənt/','不相邻的；非邻接的','两个位置没有紧挨着，或者在指定关系中没有直接连在一起。','英语 non- 不 + adjacent 相邻的；否定的是邻接关系，不一定是否定一切联系。',AD+[['英语 non- + adjacent → nonadjacent','不相邻的']], '表格可选择不相邻的单元格；图论中的非邻接顶点没有直接边，但仍可能经其他顶点相连。','nonadjacent cells；nonadjacent vertices。','disconnected 在图中还可能表示连路径都没有；nonadjacent 只保证没有直接邻接。',('Select two nonadjacent cells in the spreadsheet.','在电子表格里选择两个不相邻的单元格。'),('The two nonadjacent vertices are connected through a third vertex.','这两个非邻接顶点通过第三个顶点连通。')),
E('superjacent','英 /ˌsuːpəˈdʒeɪsənt/；美 /ˌsuːpərˈdʒeɪsənt/','位于上方的；上覆的〔少见〕','一层东西盖在另一层上面：说到覆盖在上面的那层，就换成 superjacent。','拉丁 super- 在上 + iacēre 位于 → superiacēre，借分词 superiacens 形成英语 superjacent。',J+[['拉丁 superiacēre → superiacens','位于上方、覆盖在上'],['英语 superjacent','上覆的']], '主要见于旧式或技术性的层位说明。super- 在这里讲位置在上，不是在夸它超级好。','superjacent strata；a superjacent layer。','subjacent 是在下，superjacent 是在上；overlying 是现代更常用的近义表达。',('The report compares the clay with the superjacent sand layer.','报告比较了黏土与上覆砂层。'),('The superjacent rock was removed during excavation.','开挖时移除了上覆岩石。'),sources=['https://en.wiktionary.org/wiki/superjacent']),
]
ROOT=dict(id='C0619',meaning='躺着；处于某个位置',core='不是把东西扔出去的动作，而是东西已经安放在那里：在旁边、在下面、在中间。',image='把几层物体叠放：旁边 adjacent，下面 subjacent，上面 superjacent，中间 interjacent，四周 circumjacent。',intro='拉丁 iacēre（也写 jacēre，第一人称 iaceo）说躺着、位于。它与 iacere / iacio“投掷”的历史相关，但学习时先区分状态和动作。ease、easy 的法语来源较清楚，更早能否一路接回 adiacens 尚有争议；本页保留这条常见归类，同时把不确定处说清。',forms='jac-、jacent- 常在位置词中出现；法语 gesir、giste 让 joist 看起来不再像 jac-。ease 一支的历史从可确认的古法语 aise 开始，不能用英语拼写反推已经证实的拉丁拆分。',branches=[['旁边及其关系','adjacent, adjacency, nonadjacent'],['上下、之间、四周','subjacent, superjacent, interjacent, circumjacent, circumjacency'],['托住地板的梁','joist, interjoist'],['自在与不费力〔远源有争议〕','ease, easy, easily, uneasy, unease, easygoing']],contrasts='easy 是做起来不费力，simple 是结构简单；uneasy 常是不安心，不是普通的困难。adjacent 是相邻，nonadjacent 是不直接相邻，不能都用远近代替。joist 是托梁，join 是连接，拼写近但不能混着拆。',practice='先画出上下左右的位置关系，再用前缀选词。另一边用一句话区分：The task is easy, but I feel uneasy about the deadline. 任务不难，但截止时间让我不安。',words=[],exclude={})
if __name__=='__main__':
    manifest=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text())
    original=next(r for r in manifest['roots'] if r['id']==ROOT['id'])
    ROOT['words']=[w for w in original['family'] if '-' not in w]
    expected=set(ROOT['words'])&set(manifest['owned_words']);actual={e['word'] for e in W}
    assert actual==expected,(expected-actual,actual-expected)
    assert len(W)==len(actual)
    assert all(len(e['examples'])>=2 and e['ipa'] and len(e['history'])>=2 for e in W)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'roots_batch200_vid_08.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT/'words_batch200_vid_08.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('jac:',len(W),'new words;',sum(len(e['examples']) for e in W),'bilingual examples')
